#' Convert cppRouting graph to data.frame
#'
#' @param Graph  An object generated by cppRouting::makegraph() or cpp_simplify() function.
#' @param aux logical. If \code{TRUE}, append the graph's \code{aux} weight(s), when present (a plain vector
#' becomes a column named \code{aux}; a named data.frame keeps its own column names). Silently ignored if the
#' graph has no \code{aux}.
#' @param capacity logical. If \code{TRUE}, append the graph's \code{capacity}, when present. Silently ignored
#' if the graph has no \code{capacity}.
#' @param alpha logical. If \code{TRUE}, append the graph's \code{alpha}, when present. Silently ignored if the
#' graph has no \code{alpha}.
#' @param beta logical. If \code{TRUE}, append the graph's \code{beta}, when present. Silently ignored if the
#' graph has no \code{beta}.
#' @return Data.frame with from, to and dist column, plus any of aux/capacity/alpha/beta requested.
#' @examples
#' #Simple directed graph
#'
#' edges<-data.frame(from=c(1,2,3,4,5,6,7,8),
#' to=c(0,1,2,3,6,7,8,5),
#' dist=c(1,1,1,1,1,1,1,1))
#'
#' #Construct cppRouting graph
#' graph<-makegraph(edges,directed=TRUE)
#'
#' #Convert cppRouting graph to data.frame
#'
#' df<-to_df(graph)


to_df<-function(Graph, aux = FALSE, capacity = FALSE, alpha = FALSE, beta = FALSE){
  Graph <- tag_legacy_graph(Graph)

  if (!inherits(Graph, "cppRouting_graph")) stop("Invalid graph input, must be an object generated by makegraph() or cpp_simplify() function")

  dat<-Graph$data
  dat$from<-Graph$dict$ref[match(dat$from,Graph$dict$id)]
  dat$to<-Graph$dict$ref[match(dat$to,Graph$dict$id)]

  if (isTRUE(aux) && !is.null(Graph$attrib$aux)) {
    if (is.data.frame(Graph$attrib$aux)) dat <- cbind(dat, Graph$attrib$aux) else dat$aux <- Graph$attrib$aux
  }
  if (isTRUE(capacity) && !is.null(Graph$attrib$cap)) dat$capacity <- Graph$attrib$cap
  if (isTRUE(alpha) && !is.null(Graph$attrib$alpha)) dat$alpha <- Graph$attrib$alpha
  if (isTRUE(beta) && !is.null(Graph$attrib$beta)) dat$beta <- Graph$attrib$beta

  return(dat)
}


